library(Biobase); library(SummarizedExperiment); library(survival)
base<-"/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project"; out<-file.path(base,"analysis_revisions_20260906","ECM_CAF_signature_validation"); dir.create(out,recursive=TRUE,showWarnings=FALSE)
genes<-c("COL1A1","COL3A1","FN1"); caf<-c("COL1A1","COL1A2","DCN","LUM","COL3A1","COL5A1","SPARC","FAP","PDGFRA"); my<-c("CD68","CD163","C1QA","C1QB","C1QC","LILRB1","FCER1G","TYROBP","APOC1","SPP1","MSR1")
score<-function(x,g){g<-intersect(g,rownames(x)); if(!length(g))return(rep(NA_real_,ncol(x))); colMeans(t(scale(t(x[g,,drop=FALSE]))),na.rm=TRUE)}
out_cor<-list(); out_cox<-list(); all_input<-list()
add_cohort<-function(nm,x,pd,ids,event,time,stage=NULL){
 d<-data.frame(sample_id=ids,ECM_signature=score(x,genes),CAF_score=score(x,caf),myeloid_score=score(x,my),stringsAsFactors=FALSE)
 for(g in genes)d[[g]]<-if(g%in%rownames(x))as.numeric(x[g,]) else NA_real_
 d$os_time<-suppressWarnings(as.numeric(time)); d$os_event<-as.integer(event); d$stage<-stage; d<-d[complete.cases(d[,c("ECM_signature","CAF_score","myeloid_score","os_time","os_event")]),,drop=FALSE]; d$ECM_z<-as.numeric(scale(d$ECM_signature)); all_input[[nm]]<<-d
 for(v in c("CAF_score","myeloid_score")){z<-is.finite(d$ECM_signature)&is.finite(d[[v]]); if(sum(z)>=4&&length(unique(d$ECM_signature[z]))>1&&length(unique(d[[v]][z]))>1){tt<-cor.test(d$ECM_signature[z],d[[v]][z],method="spearman",exact=FALSE);out_cor[[length(out_cor)+1]]<<-data.frame(cohort=nm,variable=v,n=sum(z),rho=unname(tt$estimate),p=tt$p.value)}}
 if(sum(d$os_event)>5){fit<-coxph(Surv(os_time,os_event)~ECM_z,data=d); sm<-summary(fit);out_cox[[length(out_cox)+1]]<<-data.frame(cohort=nm,n=nrow(d),events=sum(d$os_event),HR=exp(coef(fit)),lo=sm$conf.int[1,"lower .95"],hi=sm$conf.int[1,"upper .95"],p=sm$coefficients[1,"Pr(>|z|)"])}
 write.csv(d,file.path(out,paste0(nm,"_ECM_signature_input.csv")),row.names=FALSE)
}
parse_event<-function(x){y<-tolower(trimws(as.character(x)));as.integer(y%in%c("yes","dead","death","deceased","1","true","progression"))}; parse_time<-function(x){y<-suppressWarnings(as.numeric(gsub("[^0-9.\\-]","",as.character(x))));y[y<=0]<-NA_real_;y}
for(nm in c("GSE32894","GSE13507")){e<-readRDS(file.path(base,"00_data_audit",paste0(nm,"_expression.rds")));x<-exprs(e);fd<-as.data.frame(fData(e));sc<-intersect(c("Symbol","ILMN_Gene"),names(fd))[1];s<-toupper(trimws(as.character(fd[[sc]])));ok<-!is.na(s)&s!=""&s!="---";x<-x[ok,,drop=FALSE];s<-s[ok];sm<-rowsum(x,s,reorder=FALSE);x<-sm/as.numeric(table(s)[rownames(sm)]);pd<-pData(e);ec<-if(nm=="GSE32894")"dod_event_(yes/no):ch1" else "overall survival:ch1";tc<-if(nm=="GSE32894")"time_to_dod_(months):ch1" else "survival month:ch1";add_cohort(nm,x,pd,colnames(x),parse_event(pd[[ec]]),parse_time(pd[[tc]]))}
se<-readRDS(file.path(base,"00_data_audit","TCGA_expression.rds"));x<-assay(se);rd<-as.data.frame(rowData(se));s<-as.character(rd$gene_name);ok<-!is.na(s)&s!="";x<-x[ok,,drop=FALSE];s<-s[ok];x<-x[!duplicated(s),,drop=FALSE];rownames(x)<-s[!duplicated(s)];x<-log2(as.matrix(x)+1);pd<-read.csv(file.path(base,"00_data_audit","TCGA_clinical.csv"),check.names=FALSE,stringsAsFactors=FALSE);sid<-substr(colnames(x),1,12);m<-match(sid,pd$submitter_id);add_cohort("TCGA_BLCA",x,pd,sid,as.integer(tolower(pd$vital_status[m])=="dead"),ifelse(!is.na(pd$days_to_death[m]),pd$days_to_death[m],pd$days_to_last_follow_up[m]),pd$ajcc_pathologic_stage[m])
co<-do.call(rbind,out_cor);co$FDR<-p.adjust(co$p,"BH");cx<-do.call(rbind,out_cox);cx$FDR<-p.adjust(cx$p,"BH");write.csv(co,file.path(out,"ECM_signature_microenvironment_correlations.csv"),row.names=FALSE);write.csv(cx,file.path(out,"ECM_signature_OS_Cox.csv"),row.names=FALSE);write.csv(do.call(rbind,lapply(names(all_input),function(n){z<-all_input[[n]];z$cohort<-n;z})),file.path(out,"ECM_signature_all_input.csv"),row.names=FALSE);writeLines(c("ECM CAF signature = mean z-score of COL1A1, COL3A1, FN1","Validated in GSE32894, GSE13507, and TCGA-BLCA","Patient-level exploratory validation."),file.path(out,"RUN_STATUS.txt"));print(co);print(cx)
